import { render } from '@solidjs/web';
import './styles.css';

function App() {
  return (
    <section class="shop">
      <article class="card">
        <h2>Mug</h2>
        <p>$12</p>
      </article>
      <article class="card">
        <h2>Notebook</h2>
        <p>$8</p>
      </article>
      <article class="card">
        <h2>Pen</h2>
        <p>$3</p>
      </article>
    </section>
  );
}

render(() => <App />, document.getElementById('app'));

export default function Card(props) {
  return (
    <article class="card">
      <h2>Name</h2>
      <p>$0</p>
    </article>
  );
}

.shop {
  display: flex;
  gap: 1rem;
  font-family: sans-serif;
}

.card {
  border: 1px solid #ccc;
  border-radius: 8px;
  padding: 0.5rem 1rem;
}

import { render } from '@solidjs/web';
import Card from './card';
import './styles.css';

function App() {
  return (
    <section class="shop">
      <Card name="Mug" price={12} />
      <Card name="Notebook" price={8} />
      <Card name="Pen" price={3} />
    </section>
  );
}

render(() => <App />, document.getElementById('app'));

export default function Card(props) {
  return (
    <article class="card">
      <h2>{props.name}</h2>
      <p>${props.price}</p>
    </article>
  );
}

.shop {
  display: flex;
  gap: 1rem;
  font-family: sans-serif;
}

.card {
  border: 1px solid #ccc;
  border-radius: 8px;
  padding: 0.5rem 1rem;
}
